import React from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import authService from '../services/authService';

const AccountContainer = styled.div`
  max-width: 480px;
  margin: 0 auto;
  padding: 0;
  background-color: white;
  min-height: 100vh;
`;

const Header = styled.div`
  padding: 20px;
  border-bottom: 1px solid #eee;
`;

const Title = styled.h1`
  font-size: 18px;
  margin-bottom: 0;
`;

const ProfileSection = styled.div`
  padding: 20px;
  display: flex;
  border-bottom: 1px solid #eee;
`;

const ProfileImage = styled.div`
  width: 70px;
  height: 70px;
  border-radius: 50%;
  overflow: hidden;
  margin-right: 20px;
  position: relative;
`;

const Image = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
`;

const Badge = styled.div`
  position: absolute;
  bottom: 0;
  right: 0;
  width: 20px;
  height: 20px;
  background-color: #6c25ff;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 12px;
`;

const ProfileInfo = styled.div`
  flex: 1;
`;

const Name = styled.h2`
  font-size: 18px;
  margin-bottom: 5px;
`;

const Email = styled.p`
  color: #666;
  margin-bottom: 0;
  font-size: 14px;
`;

const Bio = styled.p`
  padding: 20px;
  color: #333;
  line-height: 1.5;
`;

const LogoutButton = styled.button`
  background-color: #f44336;
  color: white;
  border: none;
  border-radius: 4px;
  padding: 10px 20px;
  margin: 20px;
  cursor: pointer;
`;

const AccountSettings = () => {
  const navigate = useNavigate();
  const user = authService.getCurrentUser();

  const handleLogout = () => {
    authService.logout();
    navigate('/');
  };

  if (!user) {
    navigate('/login');
    return null;
  }

  return (
    <AccountContainer>
      <Header>
        <Title>Account Settings</Title>
      </Header>
      
      <ProfileSection>
        <ProfileImage>
          <Image src={`https://ui-avatars.com/api/?name=${user.name}&background=random`} alt={user.name} />
          <Badge>✓</Badge>
        </ProfileImage>
        
        <ProfileInfo>
          <Name>{user.name}</Name>
          <Email>{user.email}</Email>
        </ProfileInfo>
      </ProfileSection>
      
      <Bio>
        Lorem ipsum Dolor Sit Amet, Consectetur Adipiscing Elit, Sed Diam Nonummy Eirmod Tempor Invidunt Ut Labore Et Dolore Magna Aliquam erat, Sed Diam
      </Bio>
      
      <LogoutButton onClick={handleLogout}>Logout</LogoutButton>
    </AccountContainer>
  );
};

export default AccountSettings;
